fn all_names(deps: Map[Str, List[Str]]) -> List[Str] {
  var names: List[Str] = []
  for entry in deps.entries() {
    names = names.push(entry.key)
    names = names.concat(entry.value)
  }
  return names.unique().sort()
}

fn deps_of(deps: Map[Str, List[Str]], name: Str) -> List[Str] {
  let found = deps.get(name)
  if found.is_none() {
    return []
  }
  return found.unwrap_or([])
}

fn is_ready(deps: Map[Str, List[Str]], done: List[Str], name: Str) -> Bool {
  return deps_of(deps, name).all(fn(d) => done.contains(d))
}

pub fn topo(deps: Map[Str, List[Str]]) -> Result[List[Str], Str] {
  let names = all_names(deps)
  var done: List[Str] = []
  while done.len() < names.len() {
    let current = done
    let pick = names.find(fn(n) => not current.contains(n) and is_ready(deps, current, n))
    if pick.is_none() {
      return Err("cycle")
    }
    done = done.push(pick.unwrap_or(""))
  }
  return Ok(done)
}
